import { expect, test, type Page } from "@playwright/test";
import * as fs from "fs";
import * as path from "path";
import { getFacilityId } from "tests/support/facilityId";

/**
 * SLUG_MIN_LENGTH/SLUG_MAX_LENGTH straight from the schema module's source
 * text, not a real `import`: the tests/ TypeScript project has no `@/*`
 * alias (see tests/tsconfig.json — it's scoped to `tests/*` only), and
 * questionnaireFormSchema.ts's own import chain reaches deep into the
 * app's domain types (down through `@/types/questionnaire/question` to
 * `@careConfig`, tag configs, icon CSS side-effects...). Wiring the tests
 * project to resolve all of that just to read two numbers would mean
 * duplicating a large slice of the root tsconfig inside an isolated
 * project meant to stay Node/Playwright-only. Reading the constants'
 * source text instead still pins this assertion to the ACTUAL bound —
 * it already drifted once (25 -> 50) — without smuggling the whole `src`
 * module graph into the Playwright type-check.
 */
function readSlugBound(name: "SLUG_MIN_LENGTH" | "SLUG_MAX_LENGTH"): number {
  const schemaPath = path.resolve(
    "src/components/QuestionnaireV2/manage/questionnaireFormSchema.ts",
  );
  const source = fs.readFileSync(schemaPath, "utf-8");
  const match = source.match(new RegExp(`export const ${name}\\s*=\\s*(\\d+)`));
  if (!match) {
    throw new Error(`Could not find "${name}" in ${schemaPath}`);
  }
  return Number(match[1]);
}

const SLUG_MIN_LENGTH = readSlugBound("SLUG_MIN_LENGTH");
const SLUG_MAX_LENGTH = readSlugBound("SLUG_MAX_LENGTH");

test.use({ storageState: "tests/.auth/user.json" });

/** Counts POST requests to the questionnaire create endpoint. */
function trackCreateRequests(page: Page) {
  const requests: string[] = [];
  page.on("request", (request) => {
    if (
      request.method() === "POST" &&
      /\/api\/v1\/questionnaire\/$/.test(new URL(request.url()).pathname)
    ) {
      requests.push(request.url());
    }
  });
  return requests;
}

test.describe("Questionnaire v2 create form validation", () => {
  test("an empty title blocks the save with field errors", async ({ page }) => {
    const facilityId = getFacilityId();
    const posts = trackCreateRequests(page);

    await page.goto(`/facility/${facilityId}/settings/questionnaires/new`);
    await page.getByRole("button", { name: "Save Questionnaire" }).click();

    await expect(page.getByText("This field is required")).toBeVisible();
    await expect(page).toHaveURL(/\/questionnaires\/new$/);
    expect(posts).toHaveLength(0);
  });

  test("slug bounds and format are enforced", async ({ page }) => {
    const facilityId = getFacilityId();
    const posts = trackCreateRequests(page);
    const title = `QV2 Slug Rules ${Date.now()}`;
    const slugInput = page.getByRole("textbox", { name: "Slug" });

    await page.goto(`/facility/${facilityId}/settings/questionnaires/new`);

    await test.step("Typing a title auto-generates a slug", async () => {
      await page
        .getByRole("textbox", { name: "Title" })
        .pressSequentially(title);
      await expect(slugInput).not.toHaveValue("");
      const generated = await slugInput.inputValue();
      expect(generated.length).toBeLessThanOrEqual(SLUG_MAX_LENGTH);
      expect(generated).toMatch(/^[-\w]+$/);
    });

    await test.step("A too-short slug fails the length rule", async () => {
      await slugInput.fill("ab");
      await page.getByRole("button", { name: "Save Questionnaire" }).click();
      await expect(
        page.getByText(
          `Must be atleast ${SLUG_MIN_LENGTH} characters and atmost ${SLUG_MAX_LENGTH} characters`,
        ),
      ).toBeVisible();
      expect(posts).toHaveLength(0);
    });

    await test.step("Invalid characters fail the format rule", async () => {
      await slugInput.fill("bad slug!");
      await page.getByRole("button", { name: "Save Questionnaire" }).click();
      // The hint text also shows the format sentence, so expect two matches
      // (description + error) once the rule fires.
      await expect(
        page.getByText(
          "Slug must only contain letters, numbers, underscores, and hyphens",
        ),
      ).toHaveCount(2);
      await expect(page).toHaveURL(/\/questionnaires\/new$/);
      expect(posts).toHaveLength(0);
    });
  });
});
import { getPluginStructuredType } from "@/components/QuestionnaireV2/structured/pluginRegistry";

import { Question, QuestionType } from "@/types/questionnaire/question";
import { isCoreStructuredType } from "@/types/questionnaire/structured";

/**
 * Types the renderer never records a response for: `initializeResponses`
 * (`form/engine/store.ts`) skips `group` entirely, and `display` gets an entry
 * whose values `DisplayText` never writes — so `evaluateEnableWhen` sees
 * "unanswered" forever and a condition targeting one permanently hides its
 * question with zero feedback. The visibility card excludes them from the
 * target picker, and the save check below blocks saved/imported data that
 * already targets one. Structured questions stay eligible: they DO record
 * values through `StructuredSlot`.
 */
export const NON_RESPONSE_TYPES: QuestionType[] = ["group", "display"];

/** Tree-wide lookups built once per validation run, for checks that need to
 *  resolve a condition's target link_id against the rest of the tree. */
interface SaveCheckContext {
  typeByLinkId: Map<string, QuestionType>;
}

interface SaveCheck {
  predicate: (question: Question, context: SaveCheckContext) => boolean;
  /** i18n key for the toast shown when the predicate matches. */
  messageKey: string;
}

/**
 * Ordered save-time validation rules for the builder. Each is a pure
 * predicate over one question; the first match (pre-order DFS over the whole
 * tree) blocks the save. Add new rules here — the builder page's handleSave
 * loops over the result, so no page changes are needed.
 */
const SAVE_CHECKS: SaveCheck[] = [
  {
    // Every question needs a title.
    predicate: (question) => !question.text.trim(),
    messageKey: "question_titles_required",
  },
  {
    // Group questions must contain at least one sub-question.
    predicate: (question) =>
      question.type === "group" && (question.questions?.length ?? 0) === 0,
    messageKey: "group_needs_subquestion",
  },
  {
    // The backend rejects quantity questions carrying neither answer_option
    // nor answer_value_set, so surface a clear client-side error instead of a
    // raw 400. Grandfathered answer_option data still passes.
    predicate: (question) =>
      question.type === "quantity" &&
      !question.answer_value_set &&
      (question.answer_option?.length ?? 0) === 0,
    messageKey: "quantity_needs_valueset",
  },
  {
    // A structured question whose type resolves to nothing — neither core
    // nor a registered plugin. Saving it would persist a question no fill
    // session can render or submit, so the studio blocks it (the type
    // reappears the moment its plugin is enabled again).
    predicate: (question) =>
      question.type === "structured" &&
      (!question.structured_type ||
        (!isCoreStructuredType(question.structured_type) &&
          !getPluginStructuredType(question.structured_type))),
    messageKey: "structured_type_unknown",
  },
  {
    // A visibility condition with no target question selected. Persisting
    // such a condition would hide the question forever in fill mode (both
    // evaluators resolve link_id "" to "no response" → false), so save is
    // blocked until it's completed or removed.
    predicate: (question) =>
      question.enable_when?.some((condition) => !condition.question) ?? false,
    messageKey: "condition_target_required",
  },
  {
    // A visibility condition targeting a question that never records a
    // response (see NON_RESPONSE_TYPES) — the picker no longer offers these,
    // but saved/imported data can still carry one; it would hide the question
    // forever, so the save is blocked until it's retargeted.
    predicate: (question, { typeByLinkId }) =>
      question.enable_when?.some((condition) => {
        const targetType = typeByLinkId.get(condition.question);
        return (
          targetType !== undefined && NON_RESPONSE_TYPES.includes(targetType)
        );
      }) ?? false,
    messageKey: "condition_target_not_answerable",
  },
];

export interface SaveIssue {
  question: Question;
  messageKey: string;
}

/**
 * Every save-blocking issue in the tree, check-major (all matches of rule 1,
 * then rule 2, …) with one issue per question (its first failing rule). The
 * studio's issues popover renders the whole list; `findFirstInvalidQuestion`
 * is element 0, so the save-toast contract is unchanged.
 */
export function findInvalidQuestions(questions: Question[]): SaveIssue[] {
  const typeByLinkId = new Map<string, QuestionType>();
  const walk = (list: Question[]) => {
    for (const question of list) {
      typeByLinkId.set(question.link_id, question.type);
      walk(question.questions ?? []);
    }
  };
  walk(questions);
  const context: SaveCheckContext = { typeByLinkId };

  const issues: SaveIssue[] = [];
  const flagged = new Set<string>();
  for (const { predicate, messageKey } of SAVE_CHECKS) {
    const collect = (list: Question[]) => {
      for (const question of list) {
        if (!flagged.has(question.id) && predicate(question, context)) {
          flagged.add(question.id);
          issues.push({ question, messageKey });
        }
        collect(question.questions ?? []);
      }
    };
    collect(questions);
  }
  return issues;
}

/** The first question failing any save check, with the message to show —
 *  or undefined when the tree is saveable. */
export function findFirstInvalidQuestion(
  questions: Question[],
): SaveIssue | undefined {
  return findInvalidQuestions(questions)[0];
}

