  page: Page,
  trigger: Locator,
  {
    search,
    navigateCategories = [],
    itemIndex = 0,
    closeAfterSelect = false,
  }: SelectFromCategoryPickerOptions = {},
) {
  await trigger.waitFor({ state: "visible" });
  await trigger.scrollIntoViewIfNeeded();

